// Freemorrow: brands one Shopify notification template. Run it in the browser console on a template's
// "Edit code" page (Settings › Notifications › Customer notifications › any email › Edit code), then click Save.
// It puts brand-head.html before </head> and brand-footer.html at the top of the footer, and it replaces
// an earlier copy of either, so it is safe to run again after changing them. Paste the two files' contents
// into FM_HEAD and FM_FOOT first (build.py in this folder writes a ready-to-paste copy, apply.bundle.js).

function fmBrand(src, head, foot) {
  const strip = (s, name) => s.replace(new RegExp('<!-- fm:' + name + ' -->[\\s\\S]*?<!-- /fm:' + name + ' -->\\n?', 'g'), '');
  src = strip(strip(src, 'brand-head'), 'brand-footer');
  const done = { head: false, foot: false };
  const h = src.indexOf('</head>');
  if (h > -1) { src = src.slice(0, h) + head + src.slice(h); done.head = true; }
  // The brand block goes at the top of the footer table, ahead of Shopify's "If you have any questions" line.
  // Some templates use the disclaimer class higher up too, so look only after the footer starts.
  const start = src.search(/<table class="row footer"/);
  if (start > -1) {
    const rest = src.slice(start);
    let at = rest.search(/<p class="disclaimer__subtext"/);
    if (at < 0) {
      const box = rest.search(/<table class="container"/);
      const td = box > -1 ? rest.indexOf('<td>', box) : -1;
      at = td > -1 ? td + 4 : -1;
    }
    if (at > -1) { src = src.slice(0, start + at) + foot + src.slice(start + at); done.foot = true; }
  }
  return { src, done };
}

function fmApply(head, foot) {
  const view = document.querySelector('.cm-content').cmView.view;
  const before = view.state.doc.toString();
  const { src, done } = fmBrand(before, head, foot);
  if (src !== before) view.dispatch({ changes: { from: 0, to: before.length, insert: src } });
  return { changed: src !== before, ...done, length: src.length };
}

if (typeof module !== 'undefined') module.exports = { fmBrand };

const FM_HEAD = "<!-- fm:brand-head -->\n  <style>\n    /* Freemorrow: the same colours and type as freemorrow.com. Cream page, ink text, Instrument Serif headings,\n       Geist text, Geist Mono labels, ink pill buttons and a forest footer. Email apps without web fonts fall back\n       to Georgia and Helvetica. */\n    @font-face { font-family: 'Instrument Serif'; font-style: normal; font-weight: 400; src: url(https://fonts.gstatic.com/s/instrumentserif/v5/jizBRFtNs2ka5fXjeivQ4LroWlx-6zUTjnTLgNs.woff2) format('woff2'); }\n    @font-face { font-family: 'Instrument Serif'; font-style: italic; font-weight: 400; src: url(https://fonts.gstatic.com/s/instrumentserif/v5/jizHRFtNs2ka5fXjeivQ4LroWlx-6zAjjH7Motmp5g.woff2) format('woff2'); }\n    @font-face { font-family: 'Geist'; font-style: normal; font-weight: 400 500; src: url(https://fonts.gstatic.com/s/geist/v5/gyByhwUxId8gMEwcGFWNOITd.woff2) format('woff2'); }\n    @font-face { font-family: 'Geist Mono'; font-style: normal; font-weight: 400; src: url(https://fonts.gstatic.com/s/geistmono/v6/or3yQ6H-1_WfwkMZI_qYPLs1a-t7PU0AbeE9KK5U5Cl4PuCTfNg.woff2) format('woff2'); }\n    body, .body { background-color: #F4F1EC !important; }\n    .body td, .body p, .body span, .body a, .body li, .body h4, .body div { font-family: 'Geist', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif !important; }\n    .body h1, .body h2, .body h3 { font-family: 'Instrument Serif', Georgia, 'Times New Roman', serif !important; font-weight: 400 !important; color: #1C1917 !important; letter-spacing: -0.01em; }\n    .body h1 { font-size: 30px !important; line-height: 1.1 !important; }\n    .body h2 { font-size: 36px !important; line-height: 1.08 !important; margin: 0 0 14px !important; }\n    .body h3 { font-size: 26px !important; line-height: 1.15 !important; margin: 0 0 22px !important; }\n    .body h4 { font-family: 'Geist Mono', ui-monospace, Menlo, Consolas, monospace !important; font-size: 12px !important; font-weight: 400 !important; letter-spacing: 0.06em !important; text-transform: uppercase !important; color: #5F5E57 !important; }\n    .body p { color: #44403C !important; font-size: 15px !important; line-height: 1.6 !important; }\n    .body strong { color: #1C1917 !important; font-weight: 500 !important; }\n    .header { margin: 40px 0 28px !important; }\n    .shop-name__text a, .shop-name__text { font-family: 'Instrument Serif', Georgia, serif !important; color: #1C1917 !important; }\n    .order-number__text, .po-number__text { font-family: 'Geist Mono', ui-monospace, Menlo, Consolas, monospace !important; font-size: 12px !important; letter-spacing: 0.06em !important; text-transform: uppercase !important; color: #5F5E57 !important; }\n    .button__cell, .actions-buttons .button__cell--primary { background-color: #1C1917 !important; border-radius: 999px !important; }\n    .button__text, .actions-buttons .button__cell--primary .button__text { color: #F4F1EC !important; font-size: 15px !important; font-weight: 500 !important; }\n    .actions-buttons .button__cell--outlined { background-color: transparent !important; border: 1px solid #1C1917 !important; }\n    .actions-buttons .button__cell--outlined .button__text { color: #1C1917 !important; }\n    .button__cell--shop-app { background-color: #5A31F4 !important; }\n    a, a:hover, a:active, a:visited { color: #1C1917 !important; }\n    .link__cell, .link__cell a, .link { color: #1C1917 !important; }\n    .section__cell { border-top: 1px solid #D6D3D1 !important; }\n    .order-list__product-image, .order-list__no-product-image { background-color: #E7E1D7 !important; border: 0 !important; border-radius: 6px !important; }\n    .order-list__item-title { color: #1C1917 !important; font-weight: 500 !important; }\n    .order-list__item-variant, .order-list__item-original-price, .order-list__estimated-delivery, .order-list__delivery-method-type { color: #5F5E57 !important; }\n    .order-list__item-price, .subtotal-line__value { color: #1C1917 !important; }\n    .subtotal-line__title, .subtotal-line__title p { color: #44403C !important; }\n    .subtotal-table--total .subtotal-line__value strong { font-family: 'Instrument Serif', Georgia, serif !important; font-size: 28px !important; font-weight: 400 !important; }\n    .subtotal-spacer, .subtotal-table--total { border-color: #D6D3D1 !important; }\n    .customer-info__item-content p { color: #44403C !important; }\n    .body td.giftcard__balance { font-family: 'Instrument Serif', Georgia, 'Times New Roman', serif !important; font-size: 44px !important; font-weight: 400 !important; color: #1C1917 !important; }\n    .body td.giftcard__shop_name { font-family: 'Instrument Serif', Georgia, 'Times New Roman', serif !important; font-size: 26px !important; color: #1C1917 !important; }\n    .body td.giftcard__smalltext { font-family: 'Geist Mono', ui-monospace, Menlo, Consolas, monospace !important; font-size: 11px !important; letter-spacing: 0.06em !important; text-transform: uppercase !important; color: #5F5E57 !important; }\n    .body td.giftcard__code { font-family: 'Geist Mono', ui-monospace, Menlo, Consolas, monospace !important; letter-spacing: 0.08em !important; color: #1C1917 !important; }\n    .footer { background-color: #1C2720 !important; margin: 56px 0 0 !important; }\n    .footer__cell { padding: 44px 0 40px !important; border-top: 0 !important; }\n    .footer p, .footer .disclaimer__subtext { color: #B9B4A8 !important; font-size: 13px !important; line-height: 1.6 !important; }\n    .footer a, .footer a:visited { color: #ECE6DA !important; }\n    .footer p.fm-mark { font-family: 'Instrument Serif', Georgia, 'Times New Roman', serif !important; font-size: 30px !important; line-height: 1 !important; color: #ECE6DA !important; margin: 0 0 12px !important; }\n    .footer p.fm-tag { color: #ECE6DA !important; font-size: 15px !important; margin: 0 0 6px !important; }\n    .footer p.fm-links { font-family: 'Geist Mono', ui-monospace, Menlo, Consolas, monospace !important; font-size: 12px !important; letter-spacing: 0.06em !important; text-transform: uppercase !important; margin: 22px 0 24px !important; }\n    .footer p.fm-links a { font-family: 'Geist Mono', ui-monospace, Menlo, Consolas, monospace !important; text-decoration: none !important; color: #ECE6DA !important; }\n    .footer div.fm-rule { border-top: 1px solid #34413A !important; height: 1px; line-height: 1px; font-size: 1px; margin: 0 0 20px !important; }\n  </style>\n<!-- /fm:brand-head -->\n";
const FM_FOOT = "<!-- fm:brand-footer -->\n<p class=\"fm-mark\">Freemorrow</p>\n<p class=\"fm-tag\">Leaving the world better than we found it.</p>\n<p>All proceeds support Not For Sale's work combating human trafficking and ecocide.</p>\n<p class=\"fm-links\"><a href=\"{{ shop.url }}/collections/shop-all\">Shop</a>&nbsp;&nbsp;&middot;&nbsp;&nbsp;<a href=\"{{ shop.url }}/pages/help\">Help</a>&nbsp;&nbsp;&middot;&nbsp;&nbsp;<a href=\"{{ shop.url }}/policies/refund-policy\">Returns</a>&nbsp;&nbsp;&middot;&nbsp;&nbsp;<a href=\"https://www.instagram.com/wearefreemorrow/\">Instagram</a>&nbsp;&nbsp;&middot;&nbsp;&nbsp;<a href=\"https://www.facebook.com/profile.php?id=61591631785096\">Facebook</a></p>\n<div class=\"fm-rule\">&nbsp;</div>\n<!-- /fm:brand-footer -->\n";
fmApply(FM_HEAD, FM_FOOT);
